// === Tab: mySketch ===
var particles = [];
var trail = [];
var attractor;
var colors;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100);

	attractor = new Attractor();
	colors = [color(255, 0, 0), color(255, 153, 0), color(51, 102, 0), color(51, 102, 204)]

	for (let i = 0; i < 25; i++) {
		particles.push(new Particle(random(200, windowWidth -200), random(150, windowHeight - 150), random(5, 40)))
	}

}

class Particle {
	constructor(x, y, size) {
		this.pos = createVector(x, y);
		this.vel = createVector(random(1, 5), random(1, 5));
		this.neg = createVector(floor(random(0, 2)), floor(random(0, 2)));
		if (this.neg.x < 1) {
			this.vel.x *= -1
		}
		if (this.neg.y < 1) {
			this.vel.y *= -1
		}
		this.acc = createVector(0, 0);
		this.size = size;
		this.mass = size / 10;
		this.color = random(colors)
	}

	display() {
		noStroke();
		fill(this.color);
		ellipse(this.pos.x, this.pos.y, this.size, this.size);
	}

	update() {
		this.vel.add(this.acc);
		this.pos.add(this.vel);

		this.acc.mult(0);

		this.lifeTime--;
	}

	applyForce(force) {
		this.acc.add(force);
	}

}

class Attractor {
	constructor() {
		this.pos = createVector(windowWidth/2, windowHeight/2);
		this.mass = 50;
		this.G = 1;
		this.dragOffset = createVector(0.0, 0.0);
	}

	attract(planet) {
		var force = p5.Vector.sub(this.pos, planet.pos);
		var d = force.mag();
		d = constrain(d, 5, 25);
		force.normalize();
		var strength = (this.G * this.mass * planet.mass) / (d * d);
		force.mult(strength);

		planet.applyForce(force);
	}
}

function draw() {
	background(0);
	if (trail.length < 3000) {
		for (let i = 0; i < particles.length; i++) {
			trail.push(particles[i]);
		}
	}

	for (let i = 0; i < trail.length; i++) {
		trail[i].display();
		attractor.attract(trail[i]);
		trail[i].update();
	}
}

